const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height;

const brandColor = '#211482';
const MAX_LENGTH_CODE = 6;
const MAX_LENGTH_NUMBER = 20;

export default class Signup extends Component {
  constructor(props) {
    super(props);

    this.state = {
      isReady: true,
      isLoading: false,
      enterCode: false,
      selectedType: null,
      fontLoaded: false,
      name: '',
      phone: '',
      phoneIN: '',
      phoneLogin: '',
      phoneValid: true,
      username:'',
      usernameValid: true,
      isModalVisible: false,
      verificationId: '',
      code: '',
      OTP1:'',
      OTP2:'',
      OTP3:'',
      OTP4:'',
      OTP5:'',
      OTP6:'',
      optVarificationLoader: false,
    };

    this.setSelectedType = this.setSelectedType.bind(this);
    this.validatePhone = this.validatePhone.bind(this);
    this.signon = this.signon.bind(this);
    this._verifyCode = this._verifyCode.bind(this);
    this.auth = this.auth.bind(this);
  }


  async auth() {
    LayoutAnimation.easeInEaseOut();
    const phoneValid = await this.validatePhone();
    if (phoneValid && this.state.phoneIN!='') {
      firebase.auth()
      .verifyPhoneNumber(this.state.phoneIN)
      .on('state_changed', (phoneAuthSnapshot) => {
        switch (phoneAuthSnapshot.state) {
          
          case firebase.auth.PhoneAuthState.CODE_SENT:
            console.log('code sent');
            ToastAndroid.show('OTP sent', ToastAndroid.SHORT);
            this.setState({verificationId: phoneAuthSnapshot.verificationId});
            this.setState({ isModalVisible: true });
            break;

          case firebase.auth.PhoneAuthState.ERROR:
            //this.setState({isReady: true});
            this.setState({phone: ''});
            ToastAndroid.show('Something went wrong', ToastAndroid.SHORT);
            console.log('verification error');
            
            break;

          case firebase.auth.PhoneAuthState.AUTO_VERIFY_TIMEOUT: // or 'timeout'
            console.log('auto verify on android timed out');
            //this.setState({phone: ''});
            this.setState({isReady: true});
            
            break;
          case firebase.auth.PhoneAuthState.AUTO_VERIFIED:
            ToastAndroid.show('Auto Verified', ToastAndroid.SHORT);
            console.log('auto verified on android');
            
            // Example usage if handling here and not in optionalCompleteCb:
            const { verificationId, code } = phoneAuthSnapshot;
            const credential = firebase.auth.PhoneAuthProvider.credential(verificationId, code);
            this.signon(credential);

            break;
        }
      }, (error) => {
        // optionalErrorCb would be same logic as the ERROR case above,  if you've already handed
        // the ERROR case in the above observer then there's no need to handle it here
        console.log('error');
        ToastAndroid.show('Something went wrong', ToastAndroid.SHORT);
        this.setState({isReady: true});
        //this.setState({phone: ''});
        // verificationId is attached to error if required
        console.log(error.verificationId);
      });
    }
  }

  signon(credential){
    firebase.auth().signInWithCredential(credential).then((result) => {
                        
                        this.setState({ isModalVisible: false });
                        result.user.getIdToken().then(function(idToken) {
                          userIdToken = idToken;
                          console.log("hsabhjsa: "+idToken);
                          axios.defaults.headers.common['Authorization'] = idToken;
                          axios.defaults.headers.post['Content-Type'] = 'application/json';
                           

                          if (result.additionalUserInfo.isNewUser) {
                              this.setState({optVarificationLoader: false});
                              this.props.navigation.navigate("UserDetails");
                            }
                          else { 
                          	console.log("hsabhjsaOO");
                            axios.get('https://classcast-198812.appspot.com/users/check_if_user_exists')
                            .then(res=> {
                            	console.log("hsabhjsa"+JSON.stringify(res.data));
	                              if(res.data.status) {
	                              	this.setState({optVarificationLoader: false});
	                                ToastAndroid.show('Please wait', ToastAndroid.SHORT);
	                                this.props.navigation.navigate("Home");
	                              }
	                              else {
	                                this.setState({optVarificationLoader: false});
	                                this.props.navigation.navigate("UserDetails");
	                              }
                            })
                            .catch(err=>console.log("hsabhjsaerror"+err))
                          }
                          
                         }.bind(this));

                          }, (error) => {
                            console.log("singon error");
                            this.setState({isModalVisible: false});
                            this.setState({isReady: true});
                            this.setState({optVarificationLoader: false});
                            ToastAndroid.show('Wrong OTP', ToastAndroid.SHORT);
                          });

  }



  validatePhone() {
    const { phone, phoneIN } = this.state;
    const phoneValid = phone.length=10;
    LayoutAnimation.easeInEaseOut();
    this.setState({phoneIN: '+'+91 + ''+ phone});
    this.setState({ phoneValid });
    phoneValid || this.phoneInput.shake();
    return phoneValid;
  }


  setSelectedType = selectedType =>
    LayoutAnimation.easeInEaseOut() || this.setState({ selectedType });

  _toggleModal = () =>
    this.setState({ isModalVisible: !this.state.isModalVisible });

  _verifyCode = (val) => {
    //this.setState({code: val});
    const credential = firebase.auth.PhoneAuthProvider.credential(this.state.verificationId, val+'');
    this.signon(credential);
  }

  _onChangeText = (val) => {
    if (val.length === 6){
      this.setState({optVarificationLoader: true});
      this._verifyCode(val);
    }
  }

  componentWillMount() {
    Orientation.lockToPortrait();
    const initial = Orientation.getInitialOrientation();
  }

  componentDidMount() {
    Orientation.lockToPortrait();
  }

  render() {
    const {
      isLoading,
      selectedType,
      phone,
      phoneLogin,
      phoneValid,
      username,
      usernameValid,
      isModalVisible,
      OTP1,
      OTP2,
      OTP3,
      OTP4,
      OTP5,
      OTP6,
      phoneIN,
      verificationId
    } = this.state;

    let textStyle = this.state.enterCode ? {
      textAlign: 'center',
      fontSize: 5 * vw,
      fontWeight: 'bold',
      fontFamily: 'Courier'
    } : {};

    return (
      <ScrollView style={{backgroundColor: '#0b8dbc'}}
      contentContainerStyle ={{backgroundColor: '#0b8dbc'}}
        scrollEnabled={true}
        keyboardShouldPersistTaps="handled">
          <View style={{ flex: 1, position: 'absolute', height: SCREEN_HEIGHT, width: SCREEN_WIDTH }}>
          <Image
            style={{height: 0.4 *SCREEN_HEIGHT, width: 0.5 * SCREEN_WIDTH, position: 'absolute', alignSelf:'center', marginTop: 0.3 * SCREEN_HEIGHT}}
            resizeMode={'contain'}
            source={{uri: 'data:image/png;base64,'}}
          />
          <Modal backdropOpacity={0.6}
            backdropColor="black"
            transparent={true}
            isVisible={this.state.isModalVisible}
            onRequestClose={() => {
              this.setState({isReady: true});
              this.setState({isModalVisible: false});
          }}>
          <View style={styles.modalContent}>
                <Text style={{fontSize:6 * vw, fontFamily: 'Montserrat-SemiBold', color: '#ffffff', marginBottom: 3 * vw, textAlign: 'center'}}> Verification Code </Text>
                <Text style={{fontSize:4 * vw, fontFamily: 'Montserrat-Regular', color: '#9890da', textAlign: 'center'}}> Please type the verification code sent to +91-{this.state.phone} </Text>
                <View style={{height:50, width:'100%', marginLeft:10, marginRight:10, alignItems:'center', justifyContent: 'center', marginTop: 10}}>
                  <View style={{flexDirection:'row', flex:1, marginBottom: 10 * vw}}>
                    { !this.state.optVarificationLoader &&
                    <View style={{height: .07 * SCREEN_HEIGHT, width:'60%', marginTop:2 * vw}}>
                      <TextInput
                        ref={'textInput'}
                        name={'OTP'}
                        type={'TextInput'}
                        underlineColorAndroid={'transparent'}
                        autoCapitalize={'none'}
                        autoCorrect={false}
                        selectionColor={'white'}
                        onChangeText={this._onChangeText}
                        placeholder={this.state.enterCode ? '_ _ _ _ _ _' : 'OTP'}
                        keyboardType={'numeric'}
                        style={[ styles.textInput, textStyle, { textAlign: 'center', borderBottomColor: '#ffffff', borderBottomWidth: 3, borderRadius: 2, width: '100%', justifyContent: 'center', alignItems: 'center'} ]}
                        returnKeyType='go'
                        placeholderTextColor={'#ffffff'}
                        maxLength={6}
                        //onSubmitEditing={this._verifyCode} 
                        />
                    </View>
                  }
                  { this.state.optVarificationLoader &&
                    <View style={{height: .07 * SCREEN_HEIGHT, width:'60%', marginTop:2 * vw}}>
                      <MaterialIndicator color='white'/>
                    </View>
                  }
                  </View>
                </View>
              </View>
              
            </Modal>
          </View>
            <Image
              style={{position: 'absolute', height: 0.25 * SCREEN_WIDTH, width: 0.25 * SCREEN_WIDTH, resizeMode: 'contain', marginTop: 15 * vh, alignSelf: 'center'}}
              resizeMode={'contain'}
              source={{uri: 'data:image/png;base64,'}}
            />
          { !this.state.isReady && !this.state.isModalVisible &&
            <View style={{height: 20 * vh, width: '100%', borderRadius: 1.5 * vw, alignItems: 'center', justifyContent: 'center', marginTop: 20 * vh, position: 'absolute', paddingTop: 0.25 * SCREEN_HEIGHT}}>
              <MaterialIndicator color='white'/>
              <Text style={[styles.signUpText, {fontSize: 20, marginTop: .03 * SCREEN_HEIGHT}]}> Loading...</Text>
              
            </View>
          }
          { 
            <Text style={styles.signUpText}>{this.state.isReady ? 'Start your ClassCast journey': ''}</Text>
          }
          <Text style={styles.whoAreYouText}>What is your mobile number?</Text>
          <View style={{flexDirection: 'row', flex: 1, justifyContent: 'center', alignItems: 'center',}}>
            <View style={{width: '75%'}}>
            <FormInput
              refInput={input => (this.phoneInput = input)}
              icon="phone"
              value={phone}
              
              onChangeText={phone => this.setState({ phone })}
              placeholder="Enter your 10 digit Phone No."
              keyboardType='numeric'
              returnKeyType="next"
              errorMessage={
                phoneValid ? null : 'Please enter a valid phone address'
              }
              onSubmitEditing={() => {
                this.validatePhone();
              }}
            />
            </View>
           { this.state.isReady &&
             <TouchableNativeFeedback
              onPress={() => {
                this.setState({isReady: false});
                this.auth();
              }}
              >
               <View style={{marginLeft: .02 * SCREEN_WIDTH ,height: 0.14 * SCREEN_WIDTH, width: 0.14 * SCREEN_WIDTH, borderRadius: .07 * SCREEN_WIDTH, backgroundColor: '#ffffff', justifyContent: 'center', alignItems: 'center',}}>
                 <Image
                    style={{height: '60%', width: '60%'}}
                    source={{uri: 'data:image/png;base64,'}}
                  />
                </View>
              </TouchableNativeFeedback>
            }
            </View>
      </ScrollView>
    );
  }
}


export const FormInput = props => {
  const { icon, refInput, ...otherProps } = props;
  return (
    <Input
      {...otherProps}
      ref={refInput}
      inputContainerStyle={styles.inputContainer}
      leftIcon={<Icon name={icon} color="#ffffff" size={.06 * SCREEN_WIDTH} />}
      inputStyle={styles.inputStyle}
      autoFocus={true}
      autoCapitalize="none"
      keyboardAppearance="dark"
      errorStyle={styles.errorInputStyle}
      autoCorrect={true}
      blurOnSubmit={true}
      placeholderTextColor="#ffffff"
    />
  );
};

export const OTPInput = props => {
  const { icon, refInput, ...otherProps } = props;
  return (
    <Input
      {...otherProps}
      ref={refInput}
      inputContainerStyle={styles.OTPinputContainer}
      leftIcon={<Icon name={icon} color="#7384B4" size={18} />}
      inputStyle={styles.OTPinputStyle}
      autoFocus={false}
      autoCapitalize="none"
      keyboardAppearance="dark"
      maxLength={1}
      errorStyle={styles.errorInputStyle}
      autoCorrect={false}
      blurOnSubmit={true}
      placeholderTextColor="#7384B4"
    />
  );
};

